	["A font you choose here may lack some letters or equal-width figures. KstyleUI adds no spacing to it and uses a standard font if it fails to load."] = "Eine hier gew\195\164hlte Schrift kann manche Buchstaben oder gleich breite Ziffern vermissen lassen. KstyleUI f\195\188gt ihr keine Abst\195\164nde hinzu und verwendet eine Standardschrift, falls sie sich nicht laden l\195\164sst.",
