	["Add every profile in this string with its character and specialization choices? Its account preferences and profile hotkeys replace yours. Your other profiles stay."] = "Alle Profile aus dieser Zeichenfolge samt Charakter- und Spezialisierungszuordnung hinzuf\195\188gen? Ihre Accounteinstellungen und Profilk\195\188rzel ersetzen Eure. Eure anderen Profile bleiben.",
	["Add new to bars"] = "Neue hinzuf\195\188gen",
	["Add new tracked bars"] = "Neue verfolgte Leisten hinzuf\195\188gen",
	["Add your target to tank frames"] = "Euer Ziel zu den Tankrahmen hinzuf\195\188gen",
	["Add zeppelins, the tram, sea crossings, your hearthstone and teleports when they are faster."] = "Zeppeline, Tiefenbahn, \195\156berfahrten, Ruhestein und Teleporte nutzen, wenn sie schneller sind.",
	["Addon button"] = "Addon-Knopf",
	["Addon buttons"] = "Addon-Kn\195\182pfe",
	["Addon compartment"] = "Addon-Fach",
	["Addon drawer"] = "Addon-Schublade",
	["Addon drawer button"] = "Knopf der Addon-Schublade",
	["Addon list"] = "Addon-Liste",
	["Addon pins on the map's edge"] = "Addon-Markierungen am Kartenrand",
	["Addons"] = "Addons",
	["Adds \"mail\" after the time while mail waits for you."] = "H\195\164ngt \226\128\158Post\226\128\156 an die Uhrzeit an, solange Post auf dich wartet.",
	["Adds \"resting\" after the time while you rest in an inn or city."] = "H\195\164ngt \226\128\158erholt\226\128\156 an die Uhrzeit an, solange du dich in einem Gasthaus oder einer Stadt erholst.",
	["Adds <AFK> or <DND> after the names of away or busy players."] = "F\195\188gt <AFK> oder <DND> hinter die Namen abwesender oder besch\195\164ftigter Spieler.",
	["Adds <AFK> to the names of players who are away."] = "F\195\188gt den Namen abwesender Spieler <AFK> hinzu.",
	["Adds <DND> to the names of players who do not want to be disturbed."] = "F\195\188gt den Namen von Spielern, die nicht gest\195\182rt werden wollen, <DND> hinzu.",
	["Adds M, C, D, P or E when the game knows the debuff type. Off keeps the usual border."] = "Zeigt M, C, D, P oder E, wenn das Spiel den Schw\195\164chungstyp kennt. Aus beh\195\164lt den \195\188blichen Rand.",
	["Adds a button under the game menu that opens Layout Mode."] = "F\195\188gt unter dem Spielmen\195\188 eine Schaltfl\195\164che hinzu, die den Layoutmodus \195\182ffnet.",
	["Adds a button under the game menu that opens these settings."] = "F\195\188gt unter dem Spielmen\195\188 eine Schaltfl\195\164che hinzu, die diese Optionen \195\182ffnet.",
	["Adds a line naming the unit's target, or You in the accent colour."] = "F\195\188gt eine Zeile mit dem Ziel der Einheit hinzu, oder Ihr in der Akzentfarbe.",
	["Adds a note to import review when the shared settings change your interface size."] = "Warnt vor dem Import, wenn geteilte Einstellungen die Oberfl\195\164chengr\195\182\195\159e \195\164ndern.",
	["Adds a player's item level. Other players are inspected out of combat, a few seconds apart."] = "Zeigt die Gegenstandsstufe eines Spielers. Andere Spieler werden au\195\159erhalb des Kampfes im Abstand einiger Sekunden betrachtet.",
	["Adds a profile from a string, then switches this character to it."] = "F\195\188gt ein Profil aus einem Text hinzu und wechselt diesen Charakter darauf.",
	["Adds a searchable element list to the toolbar. Off keeps the previous drag-only toolbar."] = "Erg\195\164nzt die Leiste um eine durchsuchbare Elementliste. Aus beh\195\164lt die bisherige Leiste zum Ziehen.",
	["Adds a shield beside casts you cannot interrupt. Off keeps the usual cast bar."] = "Zeigt einen Schild neben nicht unterbrechbaren Zaubern. Aus beh\195\164lt die \195\188bliche Zauberleiste.",
	["Adds a sword for kill objectives, a bag for item objectives and the quest icon for the rest."] = "F\195\188gt ein Schwert f\195\188r T\195\182tungsziele, einen Beutel f\195\188r Gegenstandsziele und das Questsymbol f\195\188r den Rest hinzu.",
	["Adds a tick, triangle or square beside the threat border. Off keeps the border alone."] = "Zeigt Strich, Dreieck oder Quadrat neben dem Bedrohungsrand. Aus zeigt nur den Rand.",
	["Adds a tick, triangle or square beside threat colours. Off keeps the colours alone."] = "Zeigt Strich, Dreieck oder Quadrat neben den Bedrohungsfarben. Aus zeigt nur die Farben.",
	["Adds forged trim without changing the HUD layout or its colours."] = "F\195\188gt geschmiedete Verzierungen hinzu, ohne das HUD-Layout oder seine Farben zu \195\164ndern.",
	["Adds interface units to the matched height; zero matches exactly."] = "Zusatzh\195\182he in Oberfl\195\164cheneinheiten; null gleicht exakt an.",
	["Adds interface units to the matched width; zero matches exactly."] = "Zusatzbreite in Oberfl\195\164cheneinheiten; null gleicht exakt an.",
	["Adds or removes room between the title and the rows."] = "F\195\188gt Platz zwischen Titel und Zeilen hinzu oder entfernt ihn.",
	["Adds room between readouts."] = "F\195\188gt Platz zwischen Anzeigen ein.",
	["Adds the active talent loadout's name."] = "F\195\188gt den Namen der aktiven Talentkonfiguration hinzu.",
	["Adds the icon's file ID to item, spell and aura tooltips."] = "F\195\188gt Gegenstands-, Zauber- und Aura-Tooltips die Datei-ID des Symbols hinzu.",
	["Adds the item's ID to item tooltips."] = "F\195\188gt Gegenstands-Tooltips die ID des Gegenstands hinzu.",
	["Adds the maximum stack size to stackable item tooltips."] = "Zeigt die maximale Stapelgr\195\182\195\159e im Tooltip stapelbarer Gegenst\195\164nde.",
	["Adds the mount a player rides, when the game shares it."] = "Zeigt das Reittier eines Spielers, wenn das Spiel es preisgibt.",
	["Adds the player's guild rank after the guild name."] = "F\195\188gt den Gildenrang des Spielers nach dem Gildennamen hinzu.",
	["Adds the spell's ID to spell and aura tooltips."] = "F\195\188gt Zauber- und Aura-Tooltips die ID des Zaubers hinzu.",
	["Adds the spell's rank after its name, for spells that have one."] = "F\195\188gt den Rang des Zaubers nach seinem Namen hinzu, wenn er einen hat.",
	["Adds this condition to Custom visibility."] = "F\195\188gt diese Bedingung zur eigenen Sichtbarkeit hinzu.",
	["Adds this many units between aura rows, on top of Aura spacing."] = "F\195\188gt so viele Einheiten zwischen Aura-Reihen hinzu, zus\195\164tzlich zum Aura-Abstand.",
	["Adds to that one-bar move."] = "Wird zu dieser Verschiebung um eine Leiste addiert.",
	["Adds who the spell is aimed at after the spell name."] = "Zeigt hinter dem Zaubernamen, auf wen der Zauber zielt.",
	["Adds who the spell is cast on after its name, when the game shows it."] = "Zeigt nach dem Zaubernamen, auf wen er gewirkt wird, wenn das Spiel es anzeigt.",
	["Adds your energy as a thin bar beside the points."] = "Zeigt deine Energie als schmalen Balken neben den Punkten.",
	["Adds your saved instances and their resets to the clock's tooltip."] = "F\195\188gt dem Tooltip der Uhr deine gespeicherten Instanzen und ihre Zur\195\188cksetzungen hinzu.",
	["Adds your world latency to the timer, such as 1.8 (42ms)."] = "F\195\188gt dem Timer Eure Weltlatenz hinzu, etwa 1.8 (42ms).",
	["Adventure guide"] = "Abenteuerf\195\188hrer",
	["After the health"] = "Nach der Gesundheit",
	["After the health fill, or from the bar's end or start, so a shield on full health shows."] = "Nach der Gesundheitsf\195\188llung oder vom Ende oder Anfang der Leiste, damit ein Schild bei voller Gesundheit sichtbar ist.",
	["After the spell name"] = "Nach dem Zaubernamen",
	["After the spell name, or its own text on one half of the name's line."] = "Nach dem Zaubernamen oder als eigener Text auf einer H\195\164lfte der Namenszeile.",
	["After the status icons"] = "Nach den Statussymbolen",
	["After you spend mana, a spark crosses the bar for the five seconds before regeneration resumes."] = "Nachdem Ihr Mana ausgebt, quert ein Funke die Leiste f\195\188r die f\195\188nf Sekunden, bis die Regeneration wieder einsetzt.",
