	["Close this window and KstyleUI applies the DPS layout with every module on. Keep my UI leaves the game's own interface as it is."] = "Schlie\195\159t Ihr dieses Fenster, wendet KstyleUI das Schadenslayout mit allen Modulen an. Meine Oberfl\195\164che behalten l\195\164sst die Oberfl\195\164che des Spiels, wie sie ist.",
