	["Colour critical hits"] = "Kritische Treffer f\195\164rben",
	["Colour damage by its spell school, or use one colour for all damage."] = "F\195\164rbt Schaden nach seiner Zauberschule oder allen Schaden in einer Farbe.",
	["Colour each slot's border by the item's quality."] = "F\195\164rbt den Rahmen jedes Platzes nach der Qualit\195\164t des Gegenstands.",
	["Colour out of range"] = "Au\195\159er Reichweite f\195\164rben",
	["Colour the cooldown sweep of these spells."] = "F\195\164rbt die Ablaufanimation dieser Zauber.",
	["Colour the countdown numbers of these spells."] = "F\195\164rbt die Countdown-Zahlen dieser Zauber.",
	["Colour the countdown of these spells below the threshold seconds."] = "F\195\164rbt den Countdown dieser Zauber unter der Schwelle in Sekunden.",
	["Colour the crosshair while your target is beyond the reach of your spells."] = "F\195\164rbt das Fadenkreuz, solange Euer Ziel au\195\159erhalb der Reichweite Eurer Zauber ist.",
	["Colour the ready glow of these spells."] = "F\195\164rbt das Bereitschaftsleuchten dieser Zauber.",
