	["Coloured from"] = "Gef\195\164rbt nach",
	["Coloured values"] = "Farbige Werte",
	["Colours"] = "Farben",
	["Colours a debuff timer red below this many seconds. Set to zero to keep one colour."] = "F\195\164rbt die Dauer einer Schw\195\164chung unter dieser Sekundenzahl rot. Null beh\195\164lt eine Farbe bei.",
	["Colours a tiled frame's own edge in the threat colour; rows without a tile keep the border."] = "F\195\164rbt den eigenen Rand eines Rahmens mit Kachel in der Bedrohungsfarbe; Zeilen ohne Kachel behalten den Rahmen.",
	["Colours an enemy's level number by how hard it is for you."] = "F\195\164rbt die Stufe eines Feindes danach, wie schwer er f\195\188r Euch ist.",
	["Colours bars by their standing, by your class, or with one colour."] = "F\195\164rbt Leisten nach ihrem Rang, nach Eurer Klasse oder in einer Farbe.",
	["Colours casts the game marks as important, such as spells that are deadly if not interrupted."] = "F\195\164rbt Zauber, die das Spiel als wichtig markiert, etwa t\195\182dliche Zauber, die man unterbrechen muss.",
	["Colours each equipment slot's border by its item's quality."] = "F\195\164rbt den Rahmen jedes Ausr\195\188stungsplatzes nach der Qualit\195\164t seines Gegenstands.",
	["Colours each loot icon's border by its item's quality."] = "F\195\164rbt den Rahmen jedes Beutesymbols nach der Qualit\195\164t des Gegenstands.",
	["Colours each player's name in chat with their class colour."] = "F\195\164rbt den Namen jedes Spielers im Chat in seiner Klassenfarbe.",
	["Colours each roll's item border by its quality."] = "F\195\164rbt den Gegenstandsrahmen jedes Wurfs nach seiner Qualit\195\164t.",
	["Colours elites above your level."] = "F\195\164rbt Elitegegner \195\188ber Eurer Stufe.",
	["Colours enemies while they cast. Threat on the bar wins unless Threat beats unit types is off."] = "F\195\164rbt Feinde, w\195\164hrend sie zaubern. Bedrohung auf der Gesundheitsleiste hat Vorrang, au\195\159er Bedrohung vor Einheitenarten ist aus.",
	["Colours friendly NPCs' names. The current style keeps the name's own colour."] = "F\195\164rbt die Namen freundlicher NPCs. Der aktuelle Stil beh\195\164lt die eigene Namensfarbe.",
	["Colours friendly players' names. The current style keeps the name's own colour."] = "F\195\164rbt die Namen freundlicher Spieler. Der aktuelle Stil beh\195\164lt die eigene Namensfarbe.",
	["Colours links and the chat's highlights with your class colour or a colour you pick."] = "F\195\164rbt Links und die Hervorhebungen des Chats in Eurer Klassenfarbe oder einer Farbe Eurer Wahl.",
	["Colours mobs that leave you alone until you attack them."] = "F\195\164rbt Gegner, die Euch erst angreifen, wenn Ihr sie angreift.",
	["Colours names in the text colour, by class or in one colour."] = "F\195\164rbt Namen in der Textfarbe, nach Klasse oder in einer Farbe.",
	["Colours ordinary and trivial mobs. The other types win."] = "F\195\164rbt gew\195\182hnliche und triviale Gegner. Die anderen Arten haben Vorrang.",
	["Colours pet names like the raid frames' names, in the text colour or in one colour."] = "F\195\164rbt Begleiternamen wie die Namen der Schlachtzugsrahmen, in der Textfarbe oder in einer Farbe.",
	["Colours player names by class and other names by reaction."] = "F\195\164rbt Spielernamen nach Klasse und andere Namen nach Reaktion.",
	["Colours players' names with their class colour."] = "F\195\164rbt die Namen von Spielern in ihrer Klassenfarbe.",
	["Colours quest titles in quest gold instead of Blizzard's quest colours."] = "F\195\164rbt Questtitel in Questgold statt in Blizzards Questfarben.",
	["Colours target names in the text colour, by class for players or in one colour."] = "F\195\164rbt Zielnamen in der Textfarbe, bei Spielern nach Klasse oder in einer Farbe.",
	["Colours the Alliance or Horde line in its faction colour."] = "F\195\164rbt die Allianz- oder Hordezeile in der Farbe ihrer Fraktion.",
	["Colours the bar edge instead of glowing around it. Off restores the threat glow."] = "F\195\164rbt den Balkenrand. Aus stellt das Bedrohungsleuchten wieder her.",
	["Colours the bars in the friendly colour, or like the raid frames' bars."] = "F\195\164rbt die Balken in der freundlichen Farbe oder wie die Balken der Schlachtzugsrahmen.",
	["Colours the border of buttons holding an uncommon or better item."] = "F\195\164rbt den Rand von Schaltfl\195\164chen mit einem ungew\195\182hnlichen oder besseren Gegenstand.",
	["Colours the class on a player's level line in the class colour."] = "F\195\164rbt die Klasse in der Stufenzeile eines Spielers in der Klassenfarbe.",
	["Colours the clock's AM or PM with the accent."] = "F\195\164rbt AM oder PM der Uhr in der Akzentfarbe.",
	["Colours the count red below this many free slots. 0 turns it off."] = "F\195\164rbt die Zahl rot, wenn weniger Pl\195\164tze frei sind. 0 schaltet es aus.",
	["Colours the difficulty with the accent."] = "F\195\164rbt die Schwierigkeit in der Akzentfarbe.",
	["Colours the dispel overlay, edge and type icon and the aura dispel edges in the colours below."] = "F\195\164rbt Bannungs\195\188berlagerung, Rand, Typsymbol und die Bannungsr\195\164nder der Auren in den Farben unten.",
	["Colours the fps and ms labels with the accent."] = "F\195\164rbt die Beschriftungen fps und ms in der Akzentfarbe.",
	["Colours the guild like the player's name. Off uses the guild colour."] = "F\195\164rbt die Gilde wie den Spielernamen. Aus nutzt die Gildenfarbe.",
	["Colours the highlight, the debuff borders and the type icon in the colours below."] = "F\195\164rbt die Hervorhebung, die Schw\195\164chungsr\195\164nder und das Typsymbol in den Farben unten.",
	["Colours the mana in the mana colour or in one colour."] = "F\195\164rbt das Mana in der Manafarbe oder in einer Farbe.",
	["Colours the owner line like the pet's name. Off uses the owner colour."] = "F\195\164rbt die Besitzerzeile wie den Namen des Begleiters. Aus nutzt die Besitzerfarbe.",
	["Colours the percentage by your threat. Off uses the frame's text colour."] = "F\195\164rbt den Prozentwert nach Eurer Bedrohung. Aus nutzt die Textfarbe des Rahmens.",
	["Colours the plates of elites and bosses. Off, the gold diamond alone marks them."] = "F\195\164rbt die Plaketten von Elite und Bossen. Aus markiert sie nur die goldene Raute.",
	["Colours the plates of mobs one of your quests needs. Wins over the other types."] = "F\195\164rbt die Plaketten von Gegnern, die eine Eurer Quests braucht. Hat Vorrang vor den anderen Arten.",
	["Colours the plates of mobs that have mana: the ones that cast and can be interrupted."] = "F\195\164rbt die Plaketten von Gegnern mit Mana: die, die zaubern und unterbrochen werden k\195\182nnen.",
	["Colours the plates of rare and rare elite mobs."] = "F\195\164rbt die Plaketten seltener und seltener Elitegegner.",
	["Colours the red ring of each debuff by its type, such as magic or poison."] = "F\195\164rbt den roten Ring jedes Schw\195\164chungszaubers nach seiner Art, etwa Magie oder Gift.",
	["Colours the small mobs that come in swarms."] = "F\195\164rbt die kleinen Gegner, die in Schw\195\164rmen kommen.",
	["Colours the threat percent with the threat colour. Off shows it in white."] = "F\195\164rbt den Bedrohungsanteil in der Bedrohungsfarbe. Aus zeigt ihn wei\195\159.",
	["Colours the title like the NPC's name. Off uses the title colour."] = "F\195\164rbt den Titel wie den Namen des NPCs. Aus nutzt die Titelfarbe.",
	["Colours the unit's level from grey for trivial to red for far above you."] = "F\195\164rbt die Stufe der Einheit von Grau f\195\188r unbedeutend bis Rot f\195\188r weit \195\188ber dir.",
	["Colours the zone name plainly, by PvP status or with the accent."] = "F\195\164rbt den Zonennamen schlicht, nach PvP-Status oder im Akzent.",
	["Colours world bosses and skull-level mobs. Wins over rares and elites."] = "F\195\164rbt Weltbosse und Gegner mit Totenkopfstufe. Vorrang vor Seltenen und Elite.",
	["Colours your group's names inside say, yell, party, raid and instance messages."] = "F\195\164rbt die Namen deiner Gruppe in Sagen-, Schreien-, Gruppen-, Schlachtzugs- und Instanznachrichten.",
