	["Dim out of range"] = "Au\195\159er Reichweite abdunkeln",
	["Dim pinned in grids"] = "Angeheftete in Rastern abdunkeln",
	["Dim pinned items in their bag slots, since they also show in Pinned."] = "Dunkelt angeheftete Gegenst\195\164nde an ihrem Taschenplatz ab, da sie auch unter Angeheftet stehen.",
	["Dim unusable"] = "Unbenutzbare abdunkeln",
	["Dims a bar while your target is out of reach of that attack."] = "Dunkelt eine Leiste ab, solange Euer Ziel au\195\159er Reichweite dieses Angriffs ist.",
