	["Dock RestedXP's boxes"] = "RestedXP-K\195\164sten andocken",
	["Dock readouts to the meter"] = "Anzeigen am Schadensmesser andocken",
	["Docked sits under the action bars. Right rail is the old readout."] = "Angedockt sitzt unter den Aktionsleisten. Rechter Rand nutzt die alte Anzeige.",
	["Docked under the action bars"] = "Unter den Aktionsleisten angedockt",
	["Docks RestedXP's target and item boxes under the guide's card. Drag one away to keep your spot."] = "Dockt die Ziel- und Gegenstandsk\195\164sten von RestedXP unter der Guide-Karte an. Zieht einen weg, um Euren Platz zu behalten.",
	["Docks slabs into the crest, evens bars, colours power by type, sockets icons. Off: earlier slabs."] = "Dockt Platten ans Wappen, gleicht Balken an, f\195\164rbt Energie nach Typ, fasst Symbole. Aus: fr\195\188here Platten.",
	["Docks the micro menu and the bag bar under the readout, in the same card, when they are shown."] = "Dockt das Mikromen\195\188 und die Taschenleiste unter der Anzeige an, in derselben Karte, wenn sie angezeigt werden.",
	["Dodge"] = "Ausweichen",
	["Done"] = "Fertig",
	["Dots that follow the ring as the pointer moves."] = "Punkte, die dem Ring folgen, wenn sich der Zeiger bewegt.",
	["Double-click mover for settings"] = "Doppelklick \195\182ffnet Einstellungen",
	["Double-click movers for settings"] = "Doppelklick \195\182ffnet Einstellungen",
	["Double-click the header to fold"] = "Kopfzeile per Doppelklick einklappen",
	["Double-click the window's header to fold it to its header; again to open it."] = "Doppelklickt die Kopfzeile, um das Fenster darauf einzuklappen; erneut, um es zu \195\182ffnen.",
	["Double-click to open its settings."] = "Doppelklick \195\182ffnet die Einstellungen.",
	["Down"] = "Unten",
	["Down and left"] = "Nach unten und links",
	["Down and right"] = "Nach unten und rechts",
	["Down columns first"] = "Zuerst die Spalten hinunter",
	["Down from the top, or up from the foot so a lone boss sits by your combat cluster."] = "Von oben nach unten, oder vom Fu\195\159 nach oben, damit ein einzelner Boss bei Eurer Kampfgruppe steht.",
	["Down, under the cast bar"] = "Unten, unter dem Zauberbalken",
	["Downward"] = "Nach unten",
	["Drag to move. Arrows nudge one pixel; Shift uses the distance in Elements."] = "Ziehen zum Bewegen. Pfeile: ein Pixel; Umschalt nutzt den Abstand unter Elemente.",
	["Drain the fill from the other end."] = "Leert die F\195\188llung vom anderen Ende her.",
	["Draw countdowns and counts over the proc glow."] = "Zeichnet Countdowns und Z\195\164hler \195\188ber das Proc-Leuchten.",
	["Draw the values in the accent colour."] = "Zeigt die Werte in der Akzentfarbe.",
	["Drawer columns"] = "Spalten der Schublade",
	["Drawer direction"] = "Richtung der Schublade",
	["Drawer icon size"] = "Symbolgr\195\182\195\159e der Schublade",
	["Drawer opens"] = "Schublade \195\182ffnet sich",
	["Drawer spacing"] = "Abstand der Schublade",
	["Draws a KstyleUI glass panel behind the tracker."] = "Zeichnet eine KstyleUI-Glasfl\195\164che hinter die Verfolgung.",
	["Draws a border in the threat colour around members with aggro."] = "Zeichnet einen Rahmen in der Bedrohungsfarbe um Mitglieder mit Aggro.",
	["Draws a gilt line under the tooltip's title."] = "Zeichnet eine vergoldete Linie unter den Titel des Tooltips.",
	["Draws a glow and an edge around your target's plate."] = "Zeichnet ein Leuchten und eine Kante um die Plakette Eures Ziels.",
	["Draws a grid in Layout Mode, and elements snap to its lines."] = "Zeichnet im Layoutmodus ein Raster, an dessen Linien Elemente einrasten.",
	["Draws a soft shadow around KstyleUI's panels, windows and tooltips."] = "Zeichnet einen weichen Schatten um KstyleUIs Fl\195\164chen, Fenster und Tooltips.",
	["Draws a soft shadow around the chat panel."] = "Zeichnet einen weichen Schatten um die Chatfl\195\164che.",
	["Draws a strip of smoked glass behind the bar's buttons."] = "Zeichnet einen Streifen Rauchglas hinter die Kn\195\182pfe der Leiste.",
	["Draws a thin line between the cells."] = "Zeichnet eine d\195\188nne Linie zwischen den Zellen.",
	["Draws a white stripe on your own meter bar."] = "Zeichnet einen wei\195\159en Streifen auf Eure eigene Leiste.",
	["Draws cast bars over neighbouring plates."] = "Zeichnet Zauberbalken \195\188ber benachbarte Plaketten.",
	["Draws critical damage in its own colour."] = "Zeichnet kritischen Schaden in einer eigenen Farbe.",
	["Draws debuffs over neighbouring plates."] = "Zeichnet Schw\195\164chungen \195\188ber benachbarte Plaketten.",
	["Draws enemy plates larger while they cast. 1 keeps their size."] = "Zeichnet feindliche Plaketten gr\195\182\195\159er, w\195\164hrend sie zaubern. 1 beh\195\164lt ihre Gr\195\182\195\159e.",
	["Draws every label and unit in your own colour."] = "Zeichnet jede Beschriftung und Einheit in deiner eigenen Farbe.",
	["Draws every unit frame cast bar above other frames so nothing covers it."] = "Zeichnet jede Zauberleiste der Einheitenrahmen \195\188ber anderen Rahmen, damit nichts sie verdeckt.",
	["Draws extra texts 1 and 2 over the icons while Text above icons is on."] = "Zeichnet die Zusatztexte 1 und 2 \195\188ber den Symbolen, solange Text \195\188ber Symbolen an ist.",
	["Draws heal absorbs as a solid fill or in the game's heal absorb pattern."] = "Zeichnet Heilungsabsorptionen als volle F\195\188llung oder im Heilungsabsorptionsmuster des Spiels.",
	["Draws incoming heals as a faint part of the health fill. Off restores the green segment."] = "Zeigt eingehende Heilung als blassen Teil der Gesundheitsf\195\188llung. Aus: das gr\195\188ne Segment.",
	["Draws names and health text over the debuff and indicator icons, not under them."] = "Zeichnet Namen und Gesundheitstext \195\188ber den Symbolen der Schw\195\164chungszauber und Anzeiger statt darunter.",
	["Draws names over the icons while Text above icons is on."] = "Zeichnet Namen \195\188ber den Symbolen, solange Text \195\188ber Symbolen an ist.",
	["Draws role icons under the hover line, the names and the target ring."] = "Zeichnet die Rollensymbole unter die Linie beim \195\156berfahren, die Namen und den Zielring.",
	["Draws shields after the health, or back from the bar's end."] = "Zeichnet Schilde nach der Gesundheit oder vom Ende des Balkens zur\195\188ck.",
	["Draws shields as a solid fill or in the game's shield pattern."] = "Zeichnet Schilde als volle F\195\188llung oder im Schildmuster des Spiels.",
	["Draws smoked glass behind the buttons."] = "Zeichnet Rauchglas hinter die Kn\195\182pfe.",
	["Draws the bar over debuff and heal icons. Off, it sits under them, over the health bar."] = "Zeichnet die Leiste \195\188ber die Symbole der Schw\195\164chungszauber und Heilungen. Aus liegt sie darunter, \195\188ber dem Gesundheitsbalken.",
	["Draws the chamfered frame around the bar."] = "Zeichnet den abgeschr\195\164gten Rahmen um die Leiste.",
	["Draws the dispel tint under heal absorbs, shields and incoming heals, so they read through it."] = "Zeichnet die Bannf\195\164rbung unter Heilungsabsorptionen, Schilde und eingehende Heilung, damit sie lesbar bleiben.",
	["Draws the divider in the hover and target highlight colour."] = "Zeichnet die Trennlinie in der Farbe der Maus- und Zielhervorhebung.",
	["Draws the health text over the icons while Text above icons is on."] = "Zeichnet den Gesundheitstext \195\188ber den Symbolen, solange Text \195\188ber Symbolen an ist.",
	["Draws the part of a shield larger than the missing health back over the health, from the bar's end."] = "Zeichnet den Teil eines Schilds, der die fehlende Gesundheit \195\188bersteigt, vom Ende des Balkens \195\188ber die Gesundheit.",
	["Draws the strip on smoked glass."] = "Zeichnet den Streifen auf Rauchglas.",
	["Draws the strip's inner edge in the accent colour."] = "Zeichnet die Innenkante des Streifens in der Akzentfarbe.",
	["Draws your focus's cast bar taller. 1 keeps its height."] = "Zeichnet die Zauberleiste Eures Fokus h\195\182her. 1 beh\195\164lt ihre H\195\182he.",
	["Draws your target's plate larger. 1 keeps its size."] = "Zeichnet die Plakette deines Ziels gr\195\182\195\159er. 1 beh\195\164lt ihre Gr\195\182\195\159e.",
	["Drink"] = "Getr\195\164nk",
	["Drop a bag here to equip it."] = "Legt hier eine Tasche ab, um sie anzulegen.",
	["Drop a spell below, then click it with the keys and button that should cast it on a member. These are the game's Click Casting bindings."] = "Legt unten einen Zauber ab und klickt ihn dann mit den Tasten und der Maustaste an, die ihn auf ein Mitglied wirken sollen. Das sind die Klickzauber-Belegungen des Spiels.",
	["Drop a spell or macro here"] = "Zauber oder Makro hier ablegen",
	["Drops the word Level and the (Player) tag from the level line."] = "Entfernt das Wort Stufe und die Markierung (Spieler) aus der Stufenzeile.",
	["Druid bar text"] = "Text der Druidenleiste",
	["Druid mana"] = "Druidenmana",
	["Druids: shows mana in bear and cat form; the class resource bar shows the form's power."] = "Druiden: zeigt Mana in B\195\164ren- und Katzengestalt; die Klassenressource zeigt die Ressource der Gestalt.",
	["Dungeon entrances"] = "Dungeoneing\195\164nge",
	["Dungeon level ranges"] = "Dungeonstufen",
	["Dungeon: fuller plates"] = "Dungeon: gr\195\182\195\159ere Namensplaketten",
	["Dungeons"] = "Dungeons",
	["Durability"] = "Haltbarkeit",
	["Durability 96 / 100"] = "Haltbarkeit 96 / 100",
	["Duration"] = "Dauer",
	["Duration swipe"] = "Ablaufanimation",
	["During a ready check, the card warns while your mana is under 80 percent."] = "W\195\164hrend eines Bereitschaftschecks warnt die Karte, solange Euer Mana unter 80 Prozent liegt.",
	["Each buff keeps its own slot, leaving a gap while it is off you."] = "Jeder Buff beh\195\164lt seinen eigenen Platz und l\195\164sst eine L\195\188cke, solange er nicht auf Euch liegt.",
	["Each character keeps its own pins, starting from the shared ones."] = "Jeder Charakter beh\195\164lt eigene Anheftungen, ausgehend von den gemeinsamen.",
	["Each window's last lines come back after a reload or relog. Turning this off forgets them."] = "Die letzten Zeilen jedes Fensters kehren nach einem Neuladen oder erneuten Einloggen zur\195\188ck. Ausschalten vergisst sie.",
	["Earth totem"] = "Erdtotem",
	["Ease cooldown bars to a new value instead of snapping."] = "L\195\164sst Abklingzeitleisten weich zum neuen Wert gleiten, statt zu springen.",
	["Ease the fill to a new value instead of snapping."] = "L\195\164sst die F\195\188llung weich zum neuen Wert gleiten, statt zu springen.",
	["Edges buffs that have a dispel type in its colour, such as magic buffs you can purge."] = "Umrandet St\195\164rkungszauber mit Banntyp in dessen Farbe, etwa Magie, die Ihr reinigen k\195\182nnt.",
	["Edges debuffs in their dispel type's colour."] = "Umrandet Schw\195\164chungszauber in der Farbe ihres Banntyps.",
	["Edges only buffs a spell steal can take."] = "Umrandet nur St\195\164rkungszauber, die ein Zauberraub nehmen kann.",
	["Edit Mode"] = "Bearbeitungsmodus",
	["Edit Mode could not save the layout."] = "Der Bearbeitungsmodus konnte das Layout nicht speichern.",
	["Edit Mode did not take %s. %s"] = "Der Bearbeitungsmodus hat %s nicht \195\188bernommen. %s",
	["Edit Mode did not take the KstyleUI layout. Open /kstyle setup and press Try again on its summary."] = "Der Bearbeitungsmodus hat das KstyleUI-Layout nicht \195\188bernommen. \195\150ffnet /kstyle setup und dr\195\188ckt in der Zusammenfassung Erneut versuchen.",
	["Edit Mode did not take the shared layout."] = "Der Bearbeitungsmodus hat das geteilte Layout nicht \195\188bernommen.",
	["Edit Mode refused the layout's name."] = "Der Bearbeitungsmodus hat den Namen des Layouts abgelehnt.",
	["Edit Mode saved it but did not switch to it. Try again, or pick it in Edit Mode."] = "Der Bearbeitungsmodus hat es gespeichert, aber nicht dazu gewechselt. Versucht es erneut oder w\195\164hlt es im Bearbeitungsmodus.",
