	["Keybind vertical offset"] = "Vertikaler Versatz der Tastenbelegung",
	["Keybinding mode closed for combat. Unsaved bindings were discarded."] = "Der Belegungsmodus wurde wegen des Kampfes geschlossen. Ungespeicherte Belegungen wurden verworfen.",
	["Keybinding mode is unavailable on this client."] = "Der Belegungsmodus ist auf diesem Client nicht verf\195\188gbar.",
	["Keybinds cannot change in combat; try again after the fight."] = "Tastenbelegungen lassen sich im Kampf nicht \195\164ndern; versucht es nach dem Kampf erneut.",
