	["KstyleUI fonts and colours in addon panels, at their sizes. Off restores theirs; reload to apply."] = "KstyleUI-Schriften und -Farben in Addon-Fenstern, in deren Gr\195\182\195\159e. Aus stellt sie wieder her; neu laden.",
	["KstyleUI has its own settings window, with search, live previews and Layout Mode."] = "KstyleUI hat ein eigenes Optionsfenster mit Suche, Live-Vorschau und Layoutmodus.",
