	["KstyleUI icons"] = "KstyleUI-Symbole",
	["KstyleUI leaves RestedXP's item and target boxes where you put them. Turn Dock RestedXP's boxes back on in the RestedXP skin's settings."] = "KstyleUI l\195\164sst die Gegenstands- und Zielk\195\164sten von RestedXP, wo Ihr sie hingesetzt habt. Schaltet RestedXP-K\195\164sten andocken in den Optionen des RestedXP-Skins wieder ein.",
	["KstyleUI leaves the RestedXP guide where you put it. Turn Guide card back on in the RestedXP skin's settings."] = "KstyleUI l\195\164sst den RestedXP-Guide, wo Ihr ihn hingesetzt habt. Schaltet die Guide-Karte in den Optionen des RestedXP-Skins wieder ein.",
	["KstyleUI leaves the Zygor guide where you put it. Turn Guide card back on in the Zygor skin's settings."] = "KstyleUI l\195\164sst den Zygor-Guide, wo Ihr ihn hingesetzt habt. Schaltet die Guide-Karte in den Optionen des Zygor-Skins wieder ein.",
