	["Lightning Shield on the crest"] = "Blitzschlagschild am Wappen",
	["Lights combo points, holy power or soul shards as jewels on the Medallions crest ring."] = "Zeigt Combopunkte, Heilige Kraft oder Seelensplitter als Juwelen am Medaillonwappen.",
	["Lights the bar's end while shields are larger than the missing health."] = "L\195\164sst das Leistenende leuchten, solange Schilde gr\195\182\195\159er als die fehlende Gesundheit sind.",
