	["Lights the crest's right shoulder while Execute, Overpower, Revenge or Victory Rush is usable."] = "L\195\164sst die rechte Wappenschulter leuchten, solange Hinrichten, \195\156berw\195\164ltigen, Rache oder Siegesrausch nutzbar ist.",
	["Lights the frame's edge under the mouse."] = "Hebt den Rand des Rahmens unter dem Mauszeiger hervor.",
