	["Numbers each raid group above its frames while raid frames sit in groups."] = "Nummeriert jede Schlachtzugsgruppe \195\188ber ihren Rahmen, solange die Rahmen nach Gruppen sitzen.",
	["Numbers on frames start at the frame's centre, or just above it."] = "Zahlen auf Rahmen beginnen in der Rahmenmitte oder knapp dar\195\188ber.",
	["Numbers only"] = "Nur Zahlen",
	["Numbers rise straight up, arc to one side, or pop in and drift."] = "Zahlen steigen gerade auf, schwingen im Bogen zur Seite oder ploppen auf und treiben davon.",
