	["Off"] = "Aus",
	["Off by default. A format stamps player lines and the system lines the game leaves bare."] = "Standardm\195\164\195\159ig aus. Formatiert Spieler- und Systemnachrichten die das Spiel ohne l\195\164sst.",
	["Off gives boss health values two decimals too, such as 240.55K."] = "Aus zeigt auch Boss-Lebenswerte mit zwei Nachkommastellen, etwa 240.55K.",
	["Off hand"] = "Schildhand",
	["Off hides aura tooltips while you fight; they still show out of combat."] = "Aus blendet Aurentooltips im Kampf aus; au\195\159erhalb des Kampfes erscheinen sie weiter.",
	["Off hides groups 5 to 8 in a Mythic raid, where only groups 1 to 4 fight."] = "Aus blendet die Gruppen 5 bis 8 im mythischen Schlachtzug aus, wo nur die Gruppen 1 bis 4 k\195\164mpfen.",
	["Off hides leader and assistant icons while you are in combat."] = "Aus blendet Anf\195\188hrer- und Assistentensymbole aus, solange Ihr im Kampf seid.",
	["Off hides role icons while you are in combat."] = "Aus blendet Rollensymbole aus, solange Ihr im Kampf seid.",
	["Off hides the elite badge in dungeons and raids, where most enemies are elite."] = "Aus blendet das Elitesymbol in Dungeons und Schlachtz\195\188gen aus, wo die meisten Gegner Elite sind.",
	["Off keeps Details for damage; threat and swing stay available (recommended)."] = "Aus: Details misst Schaden; Bedrohung und Schwung bleiben (empfohlen).",
	["Off keeps debuff, heal and indicator tooltips hidden while you are in combat."] = "Aus blendet Tooltips von Schw\195\164chungszaubern, Heilungen und Anzeigern im Kampf aus.",
	["Off keeps your other addon for this feature (recommended)."] = "Aus: Das andere Addon \195\188bernimmt diese Funktion (empfohlen).",
	["Off keeps your other addon's bag bar (recommended)."] = "Aus: Die Taschenleiste des anderen Addons bleibt (empfohlen).",
	["Off keeps your other addon's micro menu (recommended)."] = "Aus: Das Mikromen\195\188 des anderen Addons bleibt (empfohlen).",
	["Off never shows a tooltip when you hover this frame's auras."] = "Aus zeigt nie einen Tooltip, wenn Ihr \195\188ber die Auren dieses Rahmens fahrt.",
	["Off paints the bars of dead and offline members in colours you choose."] = "Aus f\195\164rbt die Balken toter und abgemeldeter Mitglieder in Farben Eurer Wahl.",
	["Off puts the cast and global cooldown circles at the screen centre."] = "Aus setzt den Zauberkreis und den Kreis der globalen Abklingzeit in die Bildschirmmitte.",
	["Off road to %s"] = "Abseits der Stra\195\159e nach %s",
	["Off shows only the milliseconds for home and world latency."] = "Aus zeigt bei Heim- und Weltlatenz nur die Millisekunden.",
	["Off, both stay hidden until you point at them, open a bag or use Edit Mode."] = "Aus: Beide bleiben verborgen, bis du auf sie zeigst, eine Tasche \195\182ffnest oder den Bearbeitungsmodus nutzt.",
	["Off, clicks pass through friendly plates, so their names never get in the way."] = "Aus gehen Klicks durch freundliche Plaketten hindurch, sodass ihre Namen nie im Weg sind.",
	["Off, the owner line takes the pet name's size."] = "Aus \195\188bernimmt die Besitzerzeile die Gr\195\182\195\159e des Begleiternamens.",
	["Off: "] = "Aus: ",
	["Officer"] = "Offizier",
