	["Offset up"] = "Versatz senkrecht",
	["Old lines fade out when nothing new arrives. Scroll or hover to see them."] = "Alte Zeilen verblassen, wenn nichts Neues kommt. Scrollt oder fahrt dar\195\188ber, um sie zu sehen.",
	["On"] = "An",
	["On enemies, shows only the debuffs in Tracked spell IDs. Debuffs on friends show as usual."] = "Zeigt bei Feinden nur die Schw\195\164chungen aus Verfolgte Zauber-IDs. Schw\195\164chungen bei Verb\195\188ndeten erscheinen wie gewohnt.",
	["On friendly units, shows only the buffs in Tracked spell IDs. Enemy buffs show as usual."] = "Zeigt bei freundlichen Einheiten nur die St\195\164rkungen aus Verfolgte Zauber-IDs. Feindliche wie gewohnt.",
	["On its own, left"] = "Eigenst\195\164ndig, links",
	["On its own, right"] = "Eigenst\195\164ndig, rechts",
	["On mouseover"] = "Beim \195\156berfahren",
	["On nameplates, hides these spell IDs, separated by commas or spaces. Blocking wins."] = "Auf Namensplaketten diese Zauber-IDs ausblenden, mit Kommas oder Leerzeichen getrennt. Sperren gilt.",
	["On nameplates, only these spell IDs, separated by commas or spaces. Blank allows any spell."] = "Auf Namensplaketten nur diese Zauber-IDs, mit Kommas oder Leerzeichen getrennt. Leer erlaubt alle.",
	["On the bar"] = "Auf der Leiste",
	["On the frame"] = "Auf dem Rahmen",
	["On the icon"] = "Auf dem Symbol",
	["On the icon's top edge"] = "Am oberen Rand des Symbols",
	["On uses KstyleUI; Off keeps your other addon for that feature."] = "An nutzt KstyleUI; Aus beh\195\164lt Euer anderes Addon f\195\188r diese Funktion.",
	["On wider screens the HUD stays in a centred band this wide; the world still fills the screen."] = "Auf breiteren Bildschirmen bleibt das HUD in einem mittigen Streifen dieser Breite; die Welt f\195\188llt weiter den Bildschirm.",
	["On your player frame"] = "Auf Eurem Spielerrahmen",
	["On-screen alerts"] = "Bildschirmhinweise",
	["On: "] = "An: ",
	["One cast for your target"] = "Ein Zauber f\195\188r Euer Ziel",
	["One colour"] = "Eine Farbe",
	["One column with each addon's name beside its button."] = "Eine Spalte mit dem Namen jedes Addons neben seiner Taste.",
	["One combined bag with search and sorting."] = "Eine gemeinsame Tasche mit Suche und Sortierung.",
	["One grid"] = "Ein Raster",
	["One large picture of the layout you point at; arrangements on wide screens. Off: small pictures."] = "Ein gro\195\159es Bild des Layouts unter dem Zeiger; Anordnungen auf breiten Bildschirmen. Aus: kleine Bilder.",
	["One line"] = "Eine Zeile",
	["One lit glass finish on every bar, and Medallions names, levels and cast names in one typeface."] = "Ein beleuchtetes Glas auf jedem Balken, und Medallions-Namen, -Stufen und -Zaubernamen in einer Schrift.",
	["One motion style"] = "Einheitliche Bewegung",
