	["Opacity in combat"] = "Deckkraft im Kampf",
	["Opacity of cooldown sweeps. Quiet global cooldowns stay proportionally softer."] = "Deckkraft der Abklinganimation. Ruhige globale Abklingzeiten bleiben schw\195\164cher.",
	["Opacity out of combat"] = "Deckkraft au\195\159erhalb des Kampfes",
