	["Open"] = "\195\150ffnen",
	["Open Action Bars to assign your keybinds."] = "\195\150ffne die Aktionsleisten, um Tasten zu belegen.",
	["Open KstyleUI settings"] = "KstyleUI-Optionen \195\182ffnen",
	["Open and close bags"] = "Taschen \195\182ffnen und schlie\195\159en",
	["Open and close with"] = "\195\150ffnen und schlie\195\159en mit",
	["Open bags"] = "Taschen \195\182ffnen",
	["Open boxes and bags in your bags, out of combat and away from merchants, mail, banks and trades."] = "\195\150ffnet Kisten und Beutel in Euren Taschen, au\195\159erhalb des Kampfes und fern von H\195\164ndlern, Post, Banken und Handel.",
	["Open containers"] = "Beh\195\164lter \195\182ffnen",
	["Open on click"] = "Per Klick \195\182ffnen",
	["Open on mouseover"] = "Beim \195\156berfahren \195\182ffnen",
	["Open on ready check"] = "Bei Bereitschaftscheck \195\182ffnen",
	["Open settings on six common tasks. Off opens the last module page, as before."] = "\195\150ffnet sechs h\195\164ufige Aufgaben. Aus \195\182ffnet wie bisher die letzte Modulseite.",
	["Open setup to choose a damage, tank or healer layout."] = "\195\150ffne die Einrichtung und w\195\164hle ein Layout f\195\188r Schaden, Tank oder Heiler.",
	["Open the Cooldown Manager"] = "Abklingzeitmanager \195\182ffnen",
	["Open the drawer with a click, on mouseover, or keep it open."] = "\195\150ffnet die Schublade per Klick, beim \195\156berfahren oder l\195\164sst sie offen.",
	["Open the game's Click Casting"] = "Die Klickzauber des Spiels \195\182ffnen",
	["Open the member's menu"] = "Das Men\195\188 des Mitglieds \195\182ffnen",
	["Open the raid tools when a ready check starts."] = "\195\150ffnet die Schlachtzugswerkzeuge, wenn ein Bereitschaftscheck beginnt.",
	["Open the spell breakdown when you point at a player's row."] = "Die Zauberaufschl\195\188sselung beim Zeigen auf die Zeile eines Spielers \195\182ffnen.",
	["Open your bags beside the bank when you visit a banker."] = "\195\150ffnet Eure Taschen neben der Bank, wenn Ihr einen Bankier besucht.",
	["Open your bags with the character window and close them with it, unless you opened them first."] = "\195\150ffnet deine Taschen mit dem Charakterfenster und schlie\195\159t sie mit ihm, au\195\159er du hattest sie zuerst ge\195\182ffnet.",
	["Openings on the crest"] = "Gelegenheiten am Wappen",
	["Opens at level %d."] = "\195\150ffnet sich ab Stufe %d.",
	["Opens element settings on double-click. Action bars keep their own shortcut setting."] = "Doppelklick \195\182ffnet Einstellungen. Aktionsleisten behalten ihre eigene Tastenk\195\188rzel-Option.",
	["Opens the calendar; right-click for the clock options."] = "\195\150ffnet den Kalender; Rechtsklick f\195\188r die Uhroptionen.",
	["Opens the setup again to pick a layout and modules."] = "\195\150ffnet die Einrichtung erneut, um ein Layout und Module zu w\195\164hlen.",
	["Opens this bar in Options from Layout Mode. Click selects; right-click resets."] = "\195\150ffnet diese Leiste aus dem Layoutmodus. Klick w\195\164hlt, Rechtsklick setzt zur\195\188ck.",
	["Opens to"] = "\195\150ffnet mit",
	["Opposite faction only"] = "Nur gegnerische Fraktion",
	["Options search takes you straight to the setting, and the first run shows big pictures and one-click Looks."] = "Die Suche in den Optionen bringt dich direkt zur Einstellung, und der erste Start zeigt gro\195\159e Bilder und Aussehen mit einem Klick.",
	["Orbs is gone, so your HUD moved to Medallions. Frames is still here: pick it under HUD style at the top of the settings window's General page."] = "Kugeln gibt es nicht mehr, daher wurde Euer HUD auf Medaillons umgestellt. Rahmen gibt es weiterhin: W\195\164hlt ihn unter HUD-Stil oben auf der Seite Allgemein im Einstellungsfenster.",
	["Order applied"] = "Angewendete Reihenfolge",
	["Orientation"] = "Ausrichtung",
	["Original: Cinzel and Alegreya Sans"] = "Original: Cinzel und Alegreya Sans",
	["Ornaments"] = "Verzierungen",
	["Other"] = "Sonstiges",
	["Other characters"] = "Andere Charaktere",
	["Other debuffs"] = "Andere Schw\195\164chungszauber",
	["Other faction only"] = "Nur andere Fraktion",
	["Other plates' opacity"] = "Deckkraft anderer Plaketten",
	["Other usable consumables"] = "Andere benutzbare Verbrauchsgegenst\195\164nde",
	["Other-addon notices"] = "Hinweise zu anderen Addons",
	["Out of boss fights"] = "Au\195\159erhalb von Bossk\195\164mpfen",
	["Out of combat"] = "Au\195\159erhalb des Kampfes",
	["Out of combat only"] = "Nur au\195\159erhalb des Kampfes",
	["Out of combat with no target or proc, the crest only breathes slowly. Off keeps it in full motion."] = "Au\195\159erhalb des Kampfes ohne Ziel und ohne Proc atmet das Wappen nur langsam. Aus l\195\164sst es voll bewegt.",
	["Out of combat with no target, panels fade; hover, a target, a cast or combat brings them back."] = "Au\195\159erhalb des Kampfes ohne Ziel blenden Elemente aus; Zeigen, Ziel, Zauber oder Kampf holt sie zur\195\188ck.",
	["Out of combat, a card names a class buff of yours that is missing."] = "Au\195\159erhalb des Kampfes nennt eine Karte einen fehlenden St\195\164rkungszauber Eurer Klasse.",
	["Out of range"] = "Au\195\159er Reichweite",
	["Out of range colour"] = "Farbe au\195\159er Reichweite",
	["Out of range opacity"] = "Deckkraft au\195\159er Reichweite",
	["Out of range tint"] = "F\195\164rbung au\195\159er Reichweite",
	["Outline"] = "Umriss",
	["Outline colour"] = "Umrissfarbe",
	["Outline with a soft shadow"] = "Kontur mit weichem Schatten",
	["Outlines a frame in the debuff type's colour when it can be dispelled."] = "Umrandet einen Rahmen in der Farbe der Schw\195\164chungsart, wenn er sich bannen l\195\164sst.",
	["Outlines each debuff icon in its type's colour. Off keeps the plain border."] = "Umrandet jedes Schw\195\164chungssymbol in der Farbe seines Typs. Aus beh\195\164lt den schlichten Rand.",
	["Outlines the cast bar while the unit casts a spell the game marks as important."] = "Umrandet die Zauberleiste, solange die Einheit einen Zauber wirkt, den das Spiel als wichtig markiert.",
