	["Pick Keyboard or Gamepad in setup or on the General page; Gamepad sets up bars 1 and 2 for a controller."] = "W\195\164hle in der Einrichtung oder auf der Seite Allgemein Tastatur oder Controller; Controller richtet die Leisten 1 und 2 daf\195\188r ein.",
