	["Played on Frames before? Pick it here to get it back. Change it at any time in the settings window, at the top of the General page. A change made in combat waits until combat ends."] = "Habt Ihr fr\195\188her Rahmen gespielt? W\195\164hlt ihn hier, um ihn zur\195\188ckzubekommen. Ihr k\195\182nnt ihn jederzeit im Einstellungsfenster oben auf der Seite Allgemein \195\164ndern. Eine \195\132nderung im Kampf wartet, bis der Kampf endet.",
