	["Point at a layout to see it in your HUD style. You can move and resize everything later in Layout Mode: type /kstyle layout."] = "Zeigt auf ein Layout, um es in eurem HUD-Stil zu sehen. Im Layoutmodus k\195\182nnt ihr sp\195\164ter alles verschieben und skalieren: /kstyle layout.",
