	["Put the spell icon at the right end of the cast bar."] = "Setzt das Zaubersymbol an das rechte Ende des Zauberbalkens.",
	["Puts boss emotes and raid warnings on a glass lane above the target."] = "Zeigt Bossemotes und Schlachtzugswarnungen auf einer Glasbahn \195\188ber dem Ziel.",
	["Puts crowd control nearest the plate when it shares a place with enemy buffs."] = "Setzt Kontrolleffekte am n\195\164chsten an die Plakette, wenn sie sich einen Platz mit feindlichen St\195\164rkungen teilen.",
	["Puts each cast bar on its frame. Off restores both bars above the crest."] = "Setzt jede Zauberleiste an ihren Rahmen. Aus stellt beide Leisten \195\188ber dem Wappen wieder her.",
	["Puts each healer's name before the mana in a raid; a party shows the mana alone."] = "Setzt im Schlachtzug den Namen jedes Heilers vor das Mana; eine Gruppe zeigt nur das Mana.",
