	["Puts the chat buttons on the right side of the card."] = "Setzt die Chatkn\195\182pfe auf die rechte Seite der Karte.",
	["Puts the element back where its module placed it."] = "Setzt das Element dorthin zur\195\188ck, wo sein Modul es platziert hat.",
	["Puts the energy bar under or above the points."] = "Setzt die Energieleiste unter oder \195\188ber die Punkte.",
	["Puts the guide in its own card in the top left corner. Drag the guide away to keep your spot."] = "Setzt den Guide in eine eigene Karte oben links. Zieh ihn weg, um deinen Platz zu behalten.",
	["Puts the name above the health bar or on it."] = "Setzt den Namen \195\188ber den Gesundheitsbalken oder darauf.",
	["Puts the name line under the health and power bars instead of above them."] = "Setzt die Namenszeile unter den Gesundheits- und Energiebalken statt dar\195\188ber.",
	["Puts the points under the plate or above the name."] = "Setzt die Punkte unter die Plakette oder \195\188ber den Namen.",
	["Puts the power bar above the health bar, keeping the gap between them."] = "Setzt den Ressourcenbalken \195\188ber den Gesundheitsbalken und beh\195\164lt den Abstand bei.",
	["Puts the spell icon at the right of the cast bar."] = "Setzt das Zaubersymbol rechts an den Zauberbalken.",
