	["Shows KstyleUI's micro menu in place of Blizzard's. Off, Blizzard's returns."] = "Zeigt KstyleUIs Mikromen\195\188 anstelle von Blizzards. Aus kehrt Blizzards zur\195\188ck.",
	["Shows Slice and Dice and its time left as a medal on the crest's left shoulder."] = "Zeigt Zerh\195\164ckseln und seine Restzeit als Medaille an der linken Wappenschulter.",
	["Shows T, H or D in the role's colour instead of the role icon."] = "Zeigt T, H oder D in der Farbe der Rolle statt des Rollensymbols.",
	["Shows Zz while you rest in an inn or a city."] = "Zeigt Zz, solange Ihr in einem Gasthaus oder einer Stadt ruht.",
	["Shows a LibDataBroker plugin from another addon."] = "Zeigt ein LibDataBroker-Plugin eines anderen Addons.",
	["Shows a bar for your main-hand swings."] = "Zeigt eine Leiste f\195\188r Eure Schl\195\164ge mit der Waffenhand.",
	["Shows a bar for your off-hand swings."] = "Zeigt eine Leiste f\195\188r Eure Schl\195\164ge mit der Schildhand.",
	["Shows a bar for your ranged attacks."] = "Zeigt eine Leiste f\195\188r Eure Distanzangriffe.",
	["Shows a buff you can cast on members who lack it, except while the game hides auras."] = "Zeigt einen St\195\164rkungszauber, den du wirken kannst, bei Mitgliedern, denen er fehlt, au\195\159er solange das Spiel Auren verbirgt.",
	["Shows a button on the damage meter's title that clears every fight, after combat."] = "Zeigt im Titel der Schadensanzeige einen Knopf, der nach dem Kampf alle K\195\164mpfe l\195\182scht.",
	["Shows a card of the spells you cast last, like the damage meter. Move it in Layout Mode."] = "Zeigt eine Karte Eurer letzten Zauber wie die Schadensanzeige. Im Layoutmodus verschieben.",
	["Shows a crown when the unit leads the group."] = "Zeigt eine Krone, wenn die Einheit die Gruppe anf\195\188hrt.",
	["Shows a debuff's tooltip when you point at its icon."] = "Zeigt den Tooltip eines Schw\195\164chungszaubers, wenn Ihr auf sein Symbol zeigt.",
	["Shows a debuff's tooltip while you hover it. The plate behind the icon does not take the mouse."] = "Zeigt den Tooltip einer Schw\195\164chung beim \195\156berfahren. Die Plakette dahinter erh\195\164lt die Maus nicht.",
	["Shows a faction badge after the names of units flagged for PvP."] = "Zeigt ein Fraktionsabzeichen hinter den Namen von Einheiten mit PvP-Markierung.",
	["Shows a few debuffs on each frame."] = "Zeigt auf jedem Rahmen einige Schw\195\164chungszauber.",
	["Shows a friendly NPC's title, such as Innkeeper, on a line under its name."] = "Zeigt den Titel eines freundlichen NPCs, etwa Gastwirt, in einer Zeile unter seinem Namen.",
	["Shows a friendly player's guild on a line under the name."] = "Zeigt die Gilde eines freundlichen Spielers in einer Zeile unter dem Namen.",
	["Shows a heal's tooltip when you point at its icon."] = "Zeigt den Tooltip einer Heilung, wenn Ihr auf ihr Symbol zeigt.",
	["Shows a player's buffs as icons beside the tooltip whenever the game shares them."] = "Zeigt die St\195\164rkungszauber eines Spielers als Symbole neben dem Tooltip, wenn das Spiel sie preisgibt.",
	["Shows a player's guild in angle brackets, green for your own guild."] = "Zeigt die Gilde eines Spielers in spitzen Klammern, gr\195\188n f\195\188r Eure eigene Gilde.",
	["Shows a portrait beside the bars."] = "Zeigt ein Portr\195\164t neben den Leisten.",
	["Shows a strip of the spells you cast last. Move it in Layout Mode."] = "Zeigt eine Leiste Eurer letzten Zauber. Im Layoutmodus verschieben.",
	["Shows a thin mana, rage or energy bar under the health bar."] = "Zeigt eine d\195\188nne Mana-, Wut- oder Energieleiste unter dem Gesundheitsbalken.",
	["Shows a vial per weapon on the crest's lower ring that drains with its poison."] = "Zeigt pro Waffe eine Phiole am unteren Wappenring, die sich mit ihrem Gift leert.",
	["Shows absorb shields on the health bar, as the unit frames do."] = "Zeigt Absorptionsschilde auf dem Gesundheitsbalken, wie die Einheitenfenster.",
	["Shows absorb shields when incoming heals are enabled."] = "Zeigt Absorptionsschilde, wenn eingehende Heilung aktiviert ist.",
	["Shows all your profiles, character and specialization choices, account preferences and profile hotkeys as one string to copy."] = "Zeigt alle Profile, Charakter- und Spezialisierungszuordnungen, Accounteinstellungen und Profilk\195\188rzel als eine Zeichenfolge zum Kopieren.",
	["Shows an envelope while you have unread mail."] = "Zeigt einen Umschlag, solange Ihr ungelesene Post habt.",
	["Shows an eye while you are queued, in place of Blizzard's queue eye."] = "Zeigt ein Auge, solange Ihr in einer Warteschlange seid, anstelle von Blizzards Warteschlangenauge.",
	["Shows an item, spell or quest tooltip while the pointer is over its link in chat."] = "Zeigt den Tooltip eines Gegenstands, Zaubers oder einer Quest, solange der Zeiger auf dem Link ist.",
	["Shows another damage meter with its own Show and Fight. Move it in Layout Mode."] = "Zeigt eine weitere Schadensanzeige mit eigenem Anzeigen und Kampf. Im Layoutmodus verschieben.",
	["Shows boss frame health percentages with two decimal places, such as 41.27%."] = "Zeigt Gesundheitsprozente der Bossrahmen mit zwei Nachkommastellen, etwa 41.27%.",
	["Shows buffs on enemy plates in the debuffs' icon style."] = "Zeigt St\195\164rkungszauber auf Gegnerplaketten im Symbolstil der Schw\195\164chungen.",
	["Shows combo points and the druid's mana under the player frame, and the crest's class crowns."] = "Zeigt Combopunkte und das Mana des Druiden unter dem Spielerrahmen sowie die Klassenkronen am Wappen.",
	["Shows crossed swords on members who are in combat."] = "Zeigt gekreuzte Schwerter bei Mitgliedern, die im Kampf sind.",
	["Shows crossed swords while the unit is in combat."] = "Zeigt gekreuzte Schwerter, solange die Einheit im Kampf ist.",
	["Shows debuff, heal and indicator tooltips at the mouse pointer."] = "Zeigt Tooltips von Schw\195\164chungs-, Heilungs- und Indikatorsymbolen am Mauszeiger.",
	["Shows debuffs of this type; off leaves them out of every debuff row."] = "Zeigt Schw\195\164chungszauber dieser Art; aus l\195\164sst sie in jeder Reihe weg.",
	["Shows debuffs on each unit."] = "Zeigt Schw\195\164chungen auf jeder Einheit.",
	["Shows debuffs that never expire; off leaves them out of every debuff row."] = "Zeigt Schw\195\164chungszauber, die nie ablaufen; aus l\195\164sst sie in jeder Reihe weg.",
	["Shows each Lightning Shield charge as a storm orb circling the Medallions crest."] = "Zeigt jede Ladung von Blitzschlagschild als Sturmkugel, die das Medaillonwappen umkreist.",
	["Shows each Summon Hawk hawk and its time left as a perch on the Medallions crest ring."] = "Zeigt jeden beschworenen Falken und seine Restzeit als Horst am Medaillonwappen.",
	["Shows each currency's icon in place of its name."] = "Zeigt das Symbol jeder W\195\164hrung anstelle ihres Namens.",
	["Shows each debuff's type symbol, such as magic or poison, in a corner, on an edge or in the centre."] = "Zeigt das Typsymbol jedes Schw\195\164chungszaubers, etwa Magie oder Gift, in einer Ecke, an einem Rand oder in der Mitte.",
	["Shows each member's answer during a ready check."] = "Zeigt bei einem Bereitschaftscheck die Antwort jedes Mitglieds.",
	["Shows each member's portrait beside the bar."] = "Zeigt das Portr\195\164t jedes Mitglieds neben der Leiste.",
	["Shows each member's role; raid tiles show it only as Role letters or at a chosen Role icon place."] = "Zeigt die Rolle jedes Mitglieds; Schlachtzugskacheln zeigen sie nur als Rollenbuchstaben oder an einer gew\195\164hlten Position des Rollensymbols.",
	["Shows each piece of gear's item level on your equipment and on players you inspect."] = "Zeigt die Gegenstandsstufe jedes Ausr\195\188stungsteils an deiner Ausr\195\188stung und bei betrachteten Spielern.",
	["Shows each player's class or each spell's icon at the start of its row."] = "Zeigt am Anfang jeder Zeile die Klasse des Spielers oder das Symbol des Zaubers.",
	["Shows each share of the total, when the game lets addons read it."] = "Zeigt jeden Anteil am Gesamtwert, wenn das Spiel Addons ihn lesen l\195\164sst.",
	["Shows elite and rare rims, quest colours and quest progress in dungeons, raids and battlegrounds."] = "Zeigt Elite- und Rare-R\195\164nder, Questfarben und Questfortschritt in Dungeons, Schlachtz\195\188gen und Schlachtfeldern.",
	["Shows experience, or watched reputation at the level cap."] = "Zeigt Erfahrung oder auf der H\195\182chststufe den verfolgten Ruf.",
	["Shows frames per second and latency on the map."] = "Zeigt Bilder pro Sekunde und Latenz auf der Karte.",
	["Shows guild members online. Hidden when you have no guild."] = "Zeigt Gildenmitglieder online. Ohne Gilde ausgeblendet.",
	["Shows health as a percent, a value, or both."] = "Zeigt Gesundheit als Prozent, als Wert oder beides.",
	["Shows health percentages with one decimal place. Shortened health values already show one."] = "Zeigt Gesundheitsprozente mit einer Nachkommastelle. Gek\195\188rzte Gesundheitswerte zeigen bereits eine.",
	["Shows honour only in battlegrounds and world PvP, or all the time."] = "Zeigt Ehre nur in Schlachtfeldern und Welt-PvP oder immer.",
	["Shows how far your rested experience reaches past your current experience."] = "Zeigt, wie weit Eure Erholungserfahrung \195\188ber Eure aktuelle Erfahrung reicht.",
	["Shows how long KstyleUI takes each frame, refreshed while this page is open."] = "Zeigt, wie lange KstyleUI pro Bild braucht; wird aktualisiert, solange diese Seite offen ist.",
	["Shows how long the current or last fight lasted."] = "Zeigt, wie lange der aktuelle oder letzte Kampf dauerte.",
	["Shows how long you have been in combat. Move it in Layout Mode."] = "Zeigt, wie lange Ihr schon im Kampf seid. Im Layoutmodus verschieben.",
	["Shows how many times a debuff has stacked."] = "Zeigt, wie oft ein Schw\195\164chungszauber gestapelt ist.",
	["Shows incoming heals and absorb shields on the health bar."] = "Zeigt eintreffende Heilungen und Absorptionsschilde auf dem Gesundheitsbalken.",
	["Shows item counts and spell charges."] = "Zeigt Gegenstandsanzahl und Zauberaufladungen.",
	["Shows numbered channels by number and name, or by number only."] = "Zeigt nummerierte Channels mit Nummer und Name oder nur mit Nummer.",
	["Shows numbers on KstyleUI boss frames."] = "Zeigt Zahlen auf KstyleUI-Bossrahmen.",
	["Shows numbers on KstyleUI party frames."] = "Zeigt Zahlen auf KstyleUI-Gruppenrahmen.",
	["Shows numbers on KstyleUI raid frames."] = "Zeigt Zahlen auf KstyleUI-Schlachtzugsrahmen.",
	["Shows numbers on your KstyleUI focus frame."] = "Zeigt Zahlen auf Eurem KstyleUI-Fokusrahmen.",
	["Shows numbers on your KstyleUI focus-target frame."] = "Zeigt Zahlen auf Eurem KstyleUI-Rahmen f\195\188r das Ziel des Fokus.",
	["Shows numbers on your KstyleUI pet frame."] = "Zeigt Zahlen auf Eurem KstyleUI-Begleiterrahmen.",
	["Shows numbers on your KstyleUI target frame."] = "Zeigt Zahlen auf Eurem KstyleUI-Zielrahmen.",
	["Shows numbers on your KstyleUI target-of-target frame."] = "Zeigt Zahlen auf Eurem KstyleUI-Rahmen f\195\188r das Ziel des Ziels.",
	["Shows on the backpack how many slots are free in all your bags."] = "Zeigt auf dem Rucksack, wie viele Pl\195\164tze in allen Taschen frei sind.",
	["Shows online Warcraft and Battle.net friends."] = "Zeigt Freunde aus Warcraft und Battle.net online.",
	["Shows only auras you cast."] = "Zeigt nur Auren, die Ihr gewirkt habt.",
	["Shows only debuffs you can dispel; for buffs, only ones you can apply."] = "Zeigt nur bannbare Schw\195\164chungen; bei St\195\164rkungen nur solche, die du wirken kannst.",
	["Shows only debuffs your class can put on a target."] = "Zeigt nur Schw\195\164chungszauber, die Eure Klasse auf ein Ziel wirken kann.",
	["Shows possess, vehicle and override actions on this bar."] = "Zeigt Gedankenkontroll-, Fahrzeug- und Ersatzaktionen auf dieser Leiste.",
	["Shows rogue and cat form combo points as pips."] = "Zeigt Combopunkte von Schurken und Katzengestalt als Punkte.",
	["Shows shields, such as Power Word: Shield, after the health."] = "Zeigt Schilde wie Machtwort: Schild nach der Gesundheit.",
	["Shows slots with no action as empty tiles."] = "Zeigt Pl\195\164tze ohne Aktion als leere Kacheln.",
	["Shows stuns, fears and other crowd control on enemies, from anyone. Yours leaves the debuff row."] = "Zeigt Bet\195\164ubungen, Furcht und andere Kontrolleffekte auf Gegnern, von allen. Eure verlassen die Schw\195\164chungsreihe.",
	["Shows tab names in capitals or as you typed them."] = "Zeigt Reiternamen in Gro\195\159buchstaben oder so, wie Ihr sie eingegeben habt.",
	["Shows temporary weapon enchantments, such as poisons and oils, before your buffs."] = "Zeigt vor\195\188bergehende Waffenverzauberungen wie Gifte und \195\150le vor Euren St\195\164rkungszaubern.",
	["Shows tenths of a second."] = "Zeigt Zehntelsekunden.",
	["Shows the Damage Meter in KstyleUI's style when role-based meters are off, or overrides Details."] = "Zeigt die Schadensanzeige im Stil von KstyleUI, wenn rollenbasierte Anzeigen aus sind, oder hat Vorrang vor Details.",
	["Shows the PvP badge only on the other faction."] = "Zeigt das PvP-Abzeichen nur bei der anderen Fraktion.",
	["Shows the PvP badge only on units of the other faction."] = "Zeigt das PvP-Abzeichen nur bei Einheiten der anderen Fraktion.",
	["Shows the average item level of equipped gear."] = "Zeigt die durchschnittliche Gegenstandsstufe der angelegten Ausr\195\188stung.",
	["Shows the best carried item of this kind."] = "Zeigt den besten mitgef\195\188hrten Gegenstand dieser Art.",
	["Shows the bind location and Hearthstone cooldown."] = "Zeigt den Heimatort und die Abklingzeit des Ruhesteins.",
	["Shows the bound key. Below 30 units, it shows only when Count text is off."] = "Zeigt die belegte Taste. Unter 30 Einheiten nur sichtbar, wenn Anzahltext ausgeschaltet ist.",
	["Shows the card's title above the bars."] = "Zeigt den Titel der Karte \195\188ber den Leisten.",
	["Shows the chat buttons only while the pointer is over the chat."] = "Zeigt die Chatkn\195\182pfe nur, solange der Zeiger \195\188ber dem Chat ist.",
	["Shows the class reagents and ammunition you carry."] = "Zeigt die Klassenreagenzien und Munition, die du dabeihast.",
	["Shows the combat timer only while you fight."] = "Zeigt den Kampftimer nur, w\195\164hrend du k\195\164mpfst.",
	["Shows the current style's bright cast progress edge."] = "Zeigt die helle Zauberfortschrittskante des aktuellen Stils.",
	["Shows the damage and healing you take."] = "Zeigt den Schaden und die Heilung, die Ihr erhaltet.",
	["Shows the damage you take."] = "Zeigt den Schaden, den Ihr erleidet.",
	["Shows the faction badge while the unit is flagged for PvP."] = "Zeigt das Fraktionsabzeichen, solange die Einheit f\195\188r PvP markiert ist.",
	["Shows the free slots in your bags."] = "Zeigt freie Pl\195\164tze in deinen Taschen.",
	["Shows the game's chat menu, channel buttons and friends button beside the chat."] = "Zeigt das Chatmen\195\188, die Channelkn\195\182pfe und den Freundeknopf des Spiels neben dem Chat.",
	["Shows the group size and difficulty, such as 25H, while you are in a dungeon or raid."] = "Zeigt Gruppengr\195\182\195\159e und Schwierigkeit, etwa 25H, in einem Dungeon oder Schlachtzug.",
	["Shows the healing you receive, with a plus sign."] = "Zeigt die Heilung, die Ihr erhaltet, mit einem Pluszeichen.",
	["Shows the item or spell icon in the tooltip's top left corner."] = "Zeigt das Gegenstands- oder Zaubersymbol in der oberen linken Ecke des Tooltips.",
	["Shows the item, spell and icon ID lines only while this key is held."] = "Zeigt die Gegenstands-, Zauber- und Symbol-ID-Zeilen nur, solange diese Taste gehalten wird.",
	["Shows the key bound to each button."] = "Zeigt die Taste, die auf jedem Knopf liegt.",
	["Shows the link to every version's release notes, ready to copy."] = "Zeigt den Link zu den Versionshinweisen jeder Version, bereit zum Kopieren.",
	["Shows the mana, rage, energy and other power you gain, with a plus sign."] = "Zeigt Mana, Wut, Energie und andere Ressourcen, die Ihr gewinnt, mit einem Pluszeichen.",
	["Shows the maximum stack line only while this key is held."] = "Zeigt die Zeile mit der maximalen Stapelgr\195\182\195\159e nur, solange diese Taste gehalten wird.",
	["Shows the meter's name and column heading above the rows."] = "Zeigt den Namen der Anzeige und die Spalten\195\188berschrift \195\188ber den Zeilen.",
	["Shows the money earned or spent this session in the gold tooltip."] = "Zeigt im Gold-Tooltip, wie viel Geld du in dieser Sitzung verdient oder ausgegeben hast.",
	["Shows the name of each macro."] = "Zeigt den Namen jedes Makros.",
	["Shows the name of the spell being cast."] = "Zeigt den Namen des gewirkten Zaubers.",
	["Shows the open page's sections; right-click a page to fold them. Off lists pages only."] = "Zeigt die Abschnitte der offenen Seite; Rechtsklick auf eine Seite klappt sie ein. Aus zeigt nur Seiten.",
	["Shows the pins addons such as guides park on the map's edge for places off the map."] = "Zeigt die Markierungen, die Addons wie Guides f\195\188r Orte au\195\159erhalb der Karte an ihren Rand setzen.",
	["Shows the power bar on damage dealers' frames; off gives their health bar the room."] = "Zeigt den Ressourcenbalken bei Schadensverursachern; aus gibt den Platz dem Gesundheitsbalken.",
	["Shows the power bar on healers' frames; off gives their health bar the room."] = "Zeigt den Ressourcenbalken bei Heilern; aus gibt den Platz dem Gesundheitsbalken.",
	["Shows the power bar on tanks' frames; off gives their health bar the room."] = "Zeigt den Ressourcenbalken bei Tanks; aus gibt den Platz dem Gesundheitsbalken.",
	["Shows the raid marker a unit carries."] = "Zeigt die Schlachtzugsmarkierung, die eine Einheit tr\195\164gt.",
	["Shows the raid marker set on the unit."] = "Zeigt die Schlachtzugsmarkierung, die auf die Einheit gesetzt ist.",
	["Shows the raid marker, such as a skull, set on a member."] = "Zeigt die Schlachtzugsmarkierung, etwa einen Totenkopf, die auf ein Mitglied gesetzt ist.",
	["Shows the reset button only while you point at the meter."] = "Zeigt den Zur\195\188cksetzen-Knopf nur, w\195\164hrend Ihr auf die Anzeige zeigt.",
	["Shows the role icon on damage dealers."] = "Zeigt das Rollensymbol bei Schadensverursachern.",
	["Shows the role icon on healers."] = "Zeigt das Rollensymbol bei Heilern.",
	["Shows the role icon on tanks."] = "Zeigt das Rollensymbol bei Tanks.",
	["Shows the seconds left on the cast bar."] = "Zeigt die verbleibenden Sekunden auf dem Zauberbalken.",
	["Shows the seconds left until the next swing."] = "Zeigt die verbleibenden Sekunden bis zum n\195\164chsten Schlag.",
	["Shows the spell a unit is casting under its health bar."] = "Zeigt unter ihrem Gesundheitsbalken den Zauber, den eine Einheit wirkt.",
	["Shows the spell's icon at the left of the cast bar."] = "Zeigt das Symbol des Zaubers links am Zauberbalken.",
	["Shows the spell's icon beside the cast bar."] = "Zeigt das Symbol des Zaubers neben dem Zauberbalken.",
	["Shows the spell's name on the cast bar."] = "Zeigt den Namen des Zaubers auf dem Zauberbalken.",
	["Shows the text only while the pointer is over the bar."] = "Zeigt den Text nur, solange der Mauszeiger \195\188ber der Leiste ist.",
	["Shows the time left before your PvP flag drops, after the status icons."] = "Zeigt hinter den Statussymbolen, wie lange Eure PvP-Markierung noch besteht.",
	["Shows the time left on each aura."] = "Zeigt die Restzeit jeder Aura.",
	["Shows the time left on each cooldown."] = "Zeigt die Restzeit jeder Abklingzeit.",
	["Shows the time left on each icon."] = "Zeigt die Restzeit auf jedem Symbol.",
	["Shows the time left under each debuff."] = "Zeigt die Restzeit unter jedem Schw\195\164chungszauber.",
	["Shows the tracking, calendar and addon buttons only while the pointer is over the map."] = "Zeigt die Kn\195\182pfe f\195\188r Aufsp\195\188ren, Kalender und Addons nur, solange der Zeiger \195\188ber der Karte ist.",
	["Shows the type icon of a debuff you can dispel on the health bar. Off shows none."] = "Zeigt das Typsymbol einer Schw\195\164chung, die du bannen kannst, auf der Gesundheitsleiste. Aus zeigt keines.",
	["Shows the unit's buffs and debuffs beside the frame."] = "Zeigt die St\195\164rkungs- und Schw\195\164chungszauber der Einheit neben dem Rahmen.",
	["Shows the unit's casts and channels."] = "Zeigt die gewirkten und kanalisierten Zauber der Einheit.",
	["Shows the unit's group role."] = "Zeigt die Gruppenrolle der Einheit.",
	["Shows the unit's health on a KstyleUI bar under the tooltip."] = "Zeigt die Gesundheit der Einheit auf einer KstyleUI-Leiste unter dem Tooltip.",
	["Shows the unit's level in a badge on the portrait, or after the name."] = "Zeigt die Stufe der Einheit als Abzeichen am Portr\195\164t oder nach dem Namen.",
	["Shows the unit's mana, rage, energy or focus under its health."] = "Zeigt Mana, Wut, Energie oder Fokus der Einheit unter ihrer Gesundheit.",
	["Shows the unit's name."] = "Zeigt den Namen der Einheit.",
	["Shows the volume. Click: mute or unmute all sound."] = "Zeigt die Lautst\195\164rke. Klick: Ton stumm schalten oder wieder einschalten.",
	["Shows the whole name, its first or last word, or the first words as initials."] = "Zeigt den ganzen Namen, sein erstes oder letztes Wort oder die ersten W\195\182rter als Initialen.",
	["Shows the zone name under the map's left edge."] = "Zeigt den Zonennamen unter dem linken Kartenrand.",
	["Shows these states in the ready-check space. Off leaves only ready checks."] = "Zeigt diese Zust\195\164nde im Bereitschaftsplatz. Aus zeigt dort nur Bereitschaftsabfragen.",
	["Shows this button among the chat buttons."] = "Zeigt diesen Knopf bei den Chatkn\195\182pfen.",
	["Shows this indicator on party and raid frames, or on one kind only."] = "Zeigt diesen Anzeiger auf Gruppen- und Schlachtzugsrahmen oder nur auf einer Art.",
	["Shows this indicator only while you play this class, so one profile suits each character."] = "Zeigt diesen Anzeiger nur, w\195\164hrend Ihr diese Klasse spielt, damit ein Profil zu jedem Charakter passt.",
	["Shows this indicator only while your role is this one."] = "Zeigt diesen Anzeiger nur, solange Ihr diese Rolle habt.",
	["Shows this profile as a string you can copy and share."] = "Zeigt dieses Profil als Text, den Ihr kopieren und teilen k\195\182nnt.",
	["Shows this raid group's members. The groups shown close up, in order."] = "Zeigt die Mitglieder dieser Schlachtzugsgruppe. Die gezeigten Gruppen r\195\188cken der Reihe nach auf.",
	["Shows this text on every plate."] = "Zeigt diesen Text auf jeder Plakette.",
	["Shows threat only while you are in a party or raid."] = "Zeigt Bedrohung nur, solange Ihr in einer Gruppe oder einem Schlachtzug seid.",
	["Shows up to icons per row times rows debuffs; a +N chip counts the rest."] = "Zeigt bis zu Symbole pro Reihe mal Reihen Schw\195\164chungszauber; ein Abzeichen +N z\195\164hlt den Rest.",
	["Shows up to this many debuffs in a row."] = "Zeigt bis zu so viele Schw\195\164chungszauber in einer Reihe.",
	["Shows up to this many icons."] = "Zeigt bis zu so viele Symbole.",
	["Shows up to three currencies tracked in your backpack."] = "Zeigt bis zu drei im Rucksack verfolgte W\195\164hrungen.",
	["Shows where elements sit on screen and your profile's text. Off hides the preview there."] = "Zeigt, wo Elemente sitzen, und die Schrift deines Profils. Aus blendet die Vorschau dort aus.",
	["Shows who a cast targets in class colour or YOU, who interrupted it and when you can interrupt."] = "Zeigt das Ziel eines Zaubers in Klassenfarbe oder IHR, wer ihn unterbrochen hat und wann du unterbrechen kannst.",
	["Shows who target and focus casts are aimed at, who interrupted them and if you can interrupt."] = "Zeigt, auf wen Zauber von Ziel und Fokus gerichtet sind, wer sie unterbrochen hat und ob du unterbrechen kannst.",
	["Shows whose pet or minion it is on a line under a friendly pet's name."] = "Zeigt in einer Zeile unter dem Namen eines freundlichen Begleiters, wem er geh\195\182rt.",
	["Shows words such as Dodge, Parry, Absorb and Immune."] = "Zeigt W\195\182rter wie Ausweichen, Parieren, Absorbieren und Immun.",
	["Shows your Judgement on the target and its time left on the crest's right shoulder."] = "Zeigt dein Richturteil auf dem Ziel und seine Restzeit an der rechten Wappenschulter.",
	["Shows your Rupture or Garrote on the target and its time left on the crest's right shoulder."] = "Zeigt deine Blutung oder dein Erdrosseln auf dem Ziel und die Restzeit an der rechten Wappenschulter.",
	["Shows your Seal and its time left in a medal above the crest."] = "Zeigt dein Siegel und seine Restzeit in einer Medaille \195\188ber dem Wappen.",
	["Shows your combo points on your target's plate, as the unit frames' pips."] = "Zeigt deine Combopunkte auf der Plakette deines Ziels, wie die Punkte der Einheitenfenster.",
	["Shows your current zone."] = "Zeigt deine aktuelle Zone.",
