	["The room the card keeps for the chat buttons, and their column's width, in units."] = "Der Platz, den die Karte f\195\188r die Chatkn\195\182pfe freih\195\164lt, und die Breite ihrer Spalte, in Einheiten.",
	["The saved layouts are not valid."] = "Die gespeicherten Layouts sind ung\195\188ltig.",
	["The section's name. A named category with a rule sorts before the built-in sections."] = "Der Name des Abschnitts. Eine benannte Kategorie mit Regel wird vor den eingebauten Abschnitten einsortiert.",
	["The selected tab's tile edge in the accent colour, or matching the chat card's edge."] = "Der Kachelrand des gew\195\164hlten Reiters in der Akzentfarbe oder wie der Rand der Chatkarte.",
