	["The settings window is not available yet."] = "Das Optionsfenster ist noch nicht verf\195\188gbar.",
	["The shade clears as time runs out. Off fills the icon instead."] = "Der Schatten weicht, w\195\164hrend die Zeit abl\195\164uft. Aus f\195\188llt das Symbol stattdessen.",
