	["The size of the target distance text."] = "Die Gr\195\182\195\159e des Textes der Zielentfernung.",
	["The size of the text you type. The default is the message size."] = "Die Gr\195\182\195\159e des Textes, den Ihr tippt. Standard ist die Nachrichtengr\195\182\195\159e.",
	["The size of the time left; 0 sizes it to the icon."] = "Die Gr\195\182\195\159e der Restzeit; 0 richtet sie nach dem Symbol.",
	["The size of this text, before the interface text size."] = "Die Gr\195\182\195\159e dieses Texts, vor der Textgr\195\182\195\159e der Oberfl\195\164che.",
