	["The tint of a spell whose target is out of range."] = "Die F\195\164rbung eines Zaubers, dessen Ziel au\195\159er Reichweite ist.",
	["The title line's colour."] = "Die Farbe der Titelzeile.",
	["The tooltip accent when Accent colour is set to custom."] = "Der Tooltip-Akzent, wenn Akzentfarbe auf Benutzerdefiniert steht.",
	["The trainer, Legacy, RestedXP and quest tracker bars KstyleUI restyles get the same lit glass finish."] = "Die von KstyleUI gestalteten Leisten von Lehrer, Klassisch, RestedXP und Questverfolgung erhalten dasselbe beleuchtete Glas.",
	["The travel menu will be ready after combat."] = "Das Reisemen\195\188 ist nach dem Kampf bereit.",
