	["The vertical line's thickness in pixels; zero follows the style."] = "St\195\164rke der vertikalen Linie in Pixeln; null folgt dem Stil.",
	["The way Sort packs items across your bags."] = "Wie Sortieren Gegenst\195\164nde \195\188ber Eure Taschen verteilt.",
	["The way the grid fills from its first slot."] = "Wie sich das Raster von seinem ersten Platz aus f\195\188llt.",
	["The whole chat fades after a quiet spell. Hovering, typing or new player chat brings it back."] = "Der ganze Chat blendet nach einer Weile Ruhe aus. Zeiger, Tippen oder neuer Spielerchat holen ihn zur\195\188ck.",
	["The width and height of each button in the column."] = "Breite und H\195\182he jedes Knopfs in der Spalte.",
	["The width and height of each icon."] = "Breite und H\195\182he jedes Symbols.",
	["The width of each bar, icon included."] = "Die Breite jeder Leiste, samt Symbol.",
	["The width of the charge lines, in pixels."] = "Die Breite der Aufladungslinien in Pixeln.",
	["The width of the health bar, in interface units."] = "Die Breite des Lebensbalkens in Interface-Einheiten.",
	["The width the location keeps when it is fixed."] = "Die Breite, die der Ort beh\195\164lt, wenn sie fest ist.",
	["The window shrinks as soon as it needs less room. Off keeps its size until you close it."] = "Das Fenster schrumpft, sobald es weniger Platz braucht. Aus beh\195\164lt seine Gr\195\182\195\159e, bis Ihr es schlie\195\159t.",
	["The world map finds the nearest innkeeper, bank or trainer you have visited and routes by zeppelin, tram or hearth."] = "Die Weltkarte findet den n\195\164chsten besuchten Gastwirt, die Bank oder den Lehrer und plant Routen per Zeppelin, Tiefenbahn oder Ruhestein.",
	["The zoom slider's fill and the active buttons follow your class colour or your own colour."] = "Die F\195\188llung des Zoomreglers und die aktiven Kn\195\182pfe folgen Eurer Klassenfarbe oder Eurer eigenen Farbe.",
	["There is no profile named %s."] = "Es gibt kein Profil namens %s.",
	["Thick"] = "Dick",
	["Thick outline"] = "Dicker Umriss",
	["Thicker snap lines that fade in as an element snaps. Off restores the thin lines."] = "Dickere Einrastlinien, die beim Einrasten einblenden. Aus stellt die d\195\188nnen Linien wieder her.",
	["Thin"] = "D\195\188nn",
	["Thin outline"] = "D\195\188nner Umriss",
	["This account string is not valid."] = "Diese Kontozeichenfolge ist ung\195\188ltig.",
	["This character"] = "Dieser Charakter",
	["This character now uses the profile %s."] = "Dieser Charakter nutzt jetzt das Profil %s.",
