	["This fight"] = "Dieser Kampf",
	["This import changes your interface size. Review Size in General after applying."] = "Dieser Import \195\164ndert die Oberfl\195\164chengr\195\182\195\159e. Pr\195\188fe danach Gr\195\182\195\159e unter Allgemein.",
	["This is not a KstyleUI profile string. KstyleUI profile strings start with KSUI1:."] = "Das ist kein KstyleUI-Profiltext. KstyleUI-Profiltexte beginnen mit KSUI1:.",
	["This level"] = "Diese Stufe",
	["This profile comes from a newer version of KstyleUI. Update KstyleUI and try again."] = "Dieses Profil stammt aus einer neueren KstyleUI-Version. Aktualisiert KstyleUI und versucht es erneut.",
	["This profile comes from an older KstyleUI and could not be upgraded."] = "Dieses Profil stammt aus einer \195\164lteren KstyleUI-Version und lie\195\159 sich nicht aktualisieren.",
	["This profile could not be exported."] = "Dieses Profil lie\195\159 sich nicht exportieren.",
	["This profile has no settings for that module."] = "Dieses Profil enth\195\164lt keine Einstellungen f\195\188r dieses Modul.",
	["This profile string is damaged or incomplete. Copy the whole string and try again."] = "Dieser Profiltext ist besch\195\164digt oder unvollst\195\164ndig. Kopiert den ganzen Text und versucht es erneut.",
