	["This readout's icon colour. Data bar's colour follows Icon colour."] = "Die Symbolfarbe dieser Anzeige. Farbe der Datenleiste folgt der Symbolfarbe.",
	["This scoped profile is not valid."] = "Dieses Teilprofil ist ung\195\188ltig.",
	["This session"] = "Diese Sitzung",
