	["Warn out of combat when worn gear wears down."] = "Warnt au\195\159erhalb des Kampfes, wenn getragene Ausr\195\188stung verschlei\195\159t.",
	["Warn under"] = "Warnen unter",
	["Warn when any worn item falls below this durability, in percent."] = "Warnt, wenn ein getragener Gegenstand unter diese Haltbarkeit f\195\164llt, in Prozent.",
	["Warning colour"] = "Warnfarbe",
	["Warning height"] = "Warnungsh\195\182he",
	["Warns once after login when part of KstyleUI fails to load, and lists each part's state here."] = "Warnt nach dem Einloggen einmal, wenn ein Teil von KstyleUI nicht l\195\164dt, und zeigt hier den Zustand jedes Teils.",
	["Warrior"] = "Krieger",
	["Washes the health bar or the whole frame in a debuff's dispel colour."] = "T\195\182nt die Gesundheitsleiste oder den ganzen Rahmen in der Bannungsfarbe eines Schw\195\164chungszaubers.",
