	["World"] = "Welt",
	["World latency"] = "Weltlatenz",
	["World map"] = "Weltkarte",
	["World map routes"] = "Weltkarten-Routen",
	["World map routes name every step, and the last one names where you are going."] = "Weltkartenrouten benennen jeden Schritt, und der letzte nennt dein Ziel.",
	["World number font"] = "Schrift der Weltzahlen",
	["World numbers"] = "Weltzahlen",
	["World of Warcraft"] = "World of Warcraft",
