	["Wrap direction"] = "Umbruchrichtung",
	["Wrap names"] = "Namen umbrechen",
	["Wrist"] = "Handgelenke",
	["Writes % after the power percentage. Off shows the number alone."] = "Schreibt % hinter den Ressourcenprozentwert. Aus zeigt nur die Zahl.",
	["Writes 24s rather than 24."] = "Schreibt 24s statt 24.",
	["Writes F on your focus's health bar."] = "Schreibt F auf den Gesundheitsbalken Eures Fokus.",
	["Writes K, M and B in every language. Off uses the game's own number units."] = "Schreibt K, M und B in jeder Sprache. Aus nutzt die Zahleneinheiten des Spiels.",
